import pathlib,json,copy
ROOT=pathlib.Path(__file__).parent
def f(s,sec,p,text,evidence=None):
    return {'text':text,'refs':[{'source':s,'section':sec,'pages':p if isinstance(p,list) else [p]}],'evidence':evidence or text}
def code(s,sec,p,label,txt,evidence,note=None):
    return {'label':label,'code':txt,'refs':[{'source':s,'section':sec,'pages':[p]}],'evidence':evidence,'note':note}
def formula(s,sec,p,label,expr,evidence,note):
    return {'label':label,'expression':expr,'refs':[{'source':s,'section':sec,'pages':[p]}],'evidence':evidence,'note':note}
def term(name,fact):return {'term':name,'definition':fact}
def save(u):
    (ROOT/f"unit_{u['unit']:02}.json").write_text(json.dumps(u,ensure_ascii=False,indent=2),encoding='utf8')
    print('saved',u['unit'])
def label(text,fact):return {'text':text,'refs':copy.deepcopy(fact['refs']),'evidence':text}

